import React, { useEffect, useState } from "react";
import api from "../api/api";

export default function AdminDashboard(){
  const [stats, setStats] = useState({ users:0, stores:0, ratings:0 });
  const [stores, setStores] = useState([]);
  const [users, setUsers] = useState([]);
  const [newStore, setNewStore] = useState({ name: "", email: "", address: "" });
const [message, setMessage] = useState("");


  useEffect(()=>{ load(); }, []);

  const load = async () => {
    try {
      const [storesRes, usersRes] = await Promise.all([api.get("/stores"), api.get("/users")]);
      setStores(storesRes.data.stores);
      setUsers(usersRes.data.users);
      const storeCount = storesRes.data.stores.length;
      const ratingsTotal = storesRes.data.stores.reduce((a,b)=>a + (b.totalRatings||0), 0);
      setStats({ users: usersRes.data.users.length, stores: storeCount, ratings: ratingsTotal });
    } catch (err) { console.error(err); alert("Error loading admin data"); }
  };

  return (
    <div style={{padding:20}}>
      <h2>Admin Dashboard</h2>
      <div style={{display:"flex",gap:12,marginBottom:12}}>
        <div className="stat">Total Users: {stats.users}</div>
        <div className="stat">Total Stores: {stats.stores}</div>
        <div className="stat">Total Ratings: {stats.ratings}</div>
      </div>

      <h3>Stores</h3>
      <table className="table">
        <thead><tr><th>Name</th><th>Email</th><th>Address</th><th>Rating</th></tr></thead>
        <tbody>
          {stores.map(s => <tr key={s.id}><td>{s.name}</td><td>{s.email}</td><td>{s.address}</td><td>{s.averageRating}</td></tr>)}
        </tbody>
      </table>

      <h3>Users</h3>
      <table className="table">
        <thead><tr><th>Name</th><th>Email</th><th>Address</th><th>Role</th></tr></thead>
        <tbody>
          {users.map(u => <tr key={u.id}><td>{u.name}</td><td>{u.email}</td><td>{u.address}</td><td>{u.role}</td></tr>)}
        </tbody>
      </table>
    </div>
  );
}
